/**
 * Tiefgang pool from 14 Nov 2026: only prompts with at least 50 valid answers.
 * Lists are written in order of how well-known an answer is (rated by AI, Claude) – the first entry is what
 * everybody says, the last one is the rarest. `ranked()` turns that order into rarity points (10 → 95).
 * Entry format: "Name|alias|alias…".
 */
import type { KatalogPrompt } from "./tiefgang-katalog";

export function ranked(list: string[]): string[] {
  const n = list.length;
  return list.map((s, i) => {
    const [name, ...alt] = s.split("|");
    const r = Math.round(10 + 85 * Math.pow(n > 1 ? i / (n - 1) : 1, 0.85));
    return [name, String(r), ...alt].join("|");
  });
}

